@Override
    public Expression.Literal visit(ValueLiteralExpression valueLiteral) {
        DataType dataType = valueLiteral.getOutputDataType();
        LogicalType logicalType = dataType.getLogicalType();
        Optional<?> valueAs = valueLiteral.getValueAs(dataType.getConversionClass());
        Object value = null;
        if (valueAs.isPresent()) {
            value = valueAs.get();
        }
        boolean nullable = logicalType.isNullable();
        LogicalTypeRoot typeRoot = logicalType.getTypeRoot();
        switch (typeRoot) {
            case CHAR:
            case VARCHAR:
                {
                    String s = "";
                    if (value != null) {
                        s = (String) value;
                    }
                    return ExpressionCreator.string(nullable, s);
                }
            case BOOLEAN:
                {
                    boolean b = false;
                    if (value != null) {
                        b = (Boolean) value;
                    }
                    return ExpressionCreator.bool(nullable, b);
                }
            case BINARY:
            case VARBINARY:
                {
                    byte[] b = new byte[] {};
                    if (value != null) {
                        b = (byte[]) value;
                    }
                    return ExpressionCreator.binary(nullable, b);
                }
            case TINYINT:
                {
                    byte b = 0;
                    if (value != null) {
                        b = (byte) value;
                    }
                    return ExpressionCreator.i8(nullable, b);
                }
            case SMALLINT:
                {
                    short s = 0;
                    if (value != null) {
                        s = (short) value;
                    }
                    return ExpressionCreator.i16(nullable, s);
                }
            case INTEGER:
                {
                    int i = 0;
                    if (value != null) {
                        i = (int) value;
                    }
                    return ExpressionCreator.i32(nullable, i);
                }
            case BIGINT:
                {
                    long l = 0;
                    if (value != null) {
                        l = (long) value;
                    }
                    return ExpressionCreator.i64(nullable, l);
                }
            case FLOAT:
                {
                    float f = 0.0F;
                    if (value != null) {
                        f = (float) value;
                    }
                    return ExpressionCreator.fp32(nullable, f);
                }
            case DOUBLE:
                {
                    double d = 0.0;
                    if (value != null) {
                        d = (double) value;
                    }
                    return ExpressionCreator.fp64(nullable, d);
                }
            case DECIMAL:
                {
                    BigDecimal bigDecimal = new BigDecimal(0);
                    DecimalType dt = (DecimalType) logicalType;
                    if (value != null) {
                        bigDecimal = (BigDecimal) value;
                    }
                    return ExpressionCreator.decimal(
                            nullable, bigDecimal, dt.getPrecision(), dt.getScale());
                }
            case DATE:
                {
                    int days = 0;
                    if (value != null) {
                        Object o = value;
                        if (o instanceof Date || o instanceof LocalDate) {
                            days = DateTimeUtils$.MODULE$.anyToDays(o);
                        } else {
                            LOG.info("Date filter push down not supported");
                            return null;
                        }
                    }
                    return ExpressionCreator.date(nullable, days);
                }
            case TIMESTAMP_WITHOUT_TIME_ZONE:
                {
                    long micros = 0;
                    if (value != null) {
                        Long res = DateTimeUtils.toMicros(value);
                        if (res == null) {
                            LOG.warn("Timestamp filter push down not supported");
                            return null;
                        }
                        micros = res;
                    }
                    return ExpressionCreator.timestamp(nullable, micros);
                }
            case TIMESTAMP_WITH_TIME_ZONE:
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                {
                    long micros = 0;
                    if (value != null) {
                        Long res = DateTimeUtils.toMicros(value);
                        if (res == null) {
                            LOG.warn("Timestamp filter push down not supported");
                            return null;
                        }
                        micros = res;
                    }
                    return ExpressionCreator.timestampTZ(nullable, micros);
                }
            default:
                LOG.warn("Filter push down not supported");
                break;
        }
        return null;
    }

public boolean commitData(MetaInfo metaInfo, boolean changeSchema, CommitOp commitOp) {
        List<PartitionInfo> listPartitionInfo = metaInfo.getListPartitionList();
        TableInfo tableInfo = metaInfo.getTableInfo();
        List<PartitionInfo> readPartitionInfo = metaInfo.getReadPartitionInfoList();
        String tableId = tableInfo.getTableId();

        if (!"".equals(tableInfo.getTableName())) {
            updateTableShortName(
                    tableInfo.getTablePath(),
                    tableInfo.getTableId(),
                    tableInfo.getTableName(),
                    tableInfo.getTableNamespace());
        }
        updateTableProperties(tableId, tableInfo.getProperties());

        List<PartitionInfo> newPartitionList = new ArrayList<>();
        Map<String, PartitionInfo> rawMap = new HashMap<>();
        Map<String, PartitionInfo> newMap = new HashMap<>();
        Map<String, PartitionInfo> readPartitionMap = new HashMap<>();
        List<String> partitionDescList = new ArrayList<>();
        List<String> snapshotList = new ArrayList<>();

        for (PartitionInfo partitionInfo : listPartitionInfo) {
            String partitionDesc = partitionInfo.getPartitionDesc();
            rawMap.put(partitionDesc, partitionInfo);
            partitionDescList.add(partitionDesc);
            snapshotList.addAll(
                    partitionInfo.getSnapshotList().stream()
                            .map(uuid -> DBUtil.toJavaUUID(uuid).toString())
                            .collect(Collectors.toList()));
        }

        Map<String, PartitionInfo> curMap = getCurPartitionMap(tableId, partitionDescList);

        if (commitOp.equals(CommitOp.AppendCommit) || commitOp.equals(CommitOp.MergeCommit)) {
            for (PartitionInfo partitionInfo : listPartitionInfo) {
                String partitionDesc = partitionInfo.getPartitionDesc();
                PartitionInfo.Builder curPartitionInfo =
                        getOrCreateCurPartitionInfo(curMap, partitionDesc, tableId).toBuilder();
                int curVersion = curPartitionInfo.getVersion();
                int newVersion = curVersion + 1;

                curPartitionInfo
                        .setVersion(newVersion)
                        .addAllSnapshot(partitionInfo.getSnapshotList())
                        .setCommitOp(commitOp)
                        .setExpression(partitionInfo.getExpression());
                newMap.put(partitionDesc, curPartitionInfo.build());
                newPartitionList.add(curPartitionInfo.build());
            }
        } else if (commitOp.equals(CommitOp.CompactionCommit)
                || commitOp.equals(CommitOp.UpdateCommit)) {
            for (PartitionInfo p : readPartitionInfo) {
                readPartitionMap.put(p.getPartitionDesc(), p);
            }
            for (PartitionInfo partitionInfo : listPartitionInfo) {
                String partitionDesc = partitionInfo.getPartitionDesc();
                PartitionInfo.Builder curPartitionInfo =
                        getOrCreateCurPartitionInfo(curMap, partitionDesc, tableId).toBuilder();
                int curVersion = curPartitionInfo.getVersion();

                PartitionInfo readPartition = readPartitionMap.get(partitionDesc);
                int readPartitionVersion = 0;
                if (readPartition != null) {
                    readPartitionVersion = readPartition.getVersion();
                }

                int newVersion = curVersion + 1;

                if (readPartitionVersion == curVersion) {
                    curPartitionInfo
                            .clearSnapshot()
                            .addAllSnapshot(partitionInfo.getSnapshotList());
                } else {
                    Set<CommitOp> middleCommitOps =
                            partitionInfoDao.getCommitOpsBetweenVersions(
                                    tableId, partitionDesc, readPartitionVersion + 1, curVersion);
                    if (commitOp.equals(CommitOp.UpdateCommit)) {
                        if (readPartitionVersion > 0
                                && (middleCommitOps.contains(CommitOp.UpdateCommit)
                                        || (middleCommitOps.size() > 1
                                                && middleCommitOps.contains(
                                                        CommitOp.CompactionCommit)))) {
                            throw new IllegalStateException(
                                    "current operation conflicts with other data writing tasks,"
                                            + " table path: "
                                            + tableInfo.getTablePath()
                                            + ", readPartitionVersion: "
                                            + readPartitionVersion
                                            + ", curVersion: "
                                            + curVersion
                                            + ", middleCommitOps: "
                                            + middleCommitOps);
                        } else if (middleCommitOps.size() == 1
                                && middleCommitOps.contains(CommitOp.CompactionCommit)) {
                            List<PartitionInfo> midPartitions =
                                    getIncrementalPartitions(
                                            tableId,
                                            partitionDesc,
                                            readPartitionVersion + 1,
                                            curVersion);
                            for (PartitionInfo p : midPartitions) {
                                if (p.getCommitOp().equals(CommitOp.CompactionCommit)
                                        && p.getSnapshotCount() > 1) {
                                    throw new IllegalStateException(
                                            "current operation conflicts with other data writing"
                                                    + " tasks, table path: "
                                                    + tableInfo.getTablePath());
                                }
                            }
                        }
                        curPartitionInfo
                                .clearSnapshot()
                                .addAllSnapshot(partitionInfo.getSnapshotList());
                    } else {
                        if (middleCommitOps.contains(CommitOp.UpdateCommit)
                                || middleCommitOps.contains(CommitOp.CompactionCommit)) {
                            partitionDescList.remove(partitionDesc);
                            snapshotList.removeAll(
                                    partitionInfo.getSnapshotList().stream()
                                            .map(uuid -> DBUtil.toJavaUUID(uuid).toString())
                                            .collect(Collectors.toList()));
                            continue;
                        }
                        curPartitionInfo =
                                updateSubmitPartitionSnapshot(
                                        partitionInfo, curPartitionInfo, readPartition);
                    }
                }

                curPartitionInfo.setVersion(newVersion);
                curPartitionInfo.setCommitOp(commitOp);
                curPartitionInfo.setExpression(partitionInfo.getExpression());

                newMap.put(partitionDesc, curPartitionInfo.build());
                newPartitionList.add(curPartitionInfo.build());
            }
        } else if (commitOp.equals(CommitOp.DeleteCommit)) {
            for (PartitionInfo p : readPartitionInfo) {
                readPartitionMap.put(p.getPartitionDesc(), p);
            }

            for (PartitionInfo partitionInfo : listPartitionInfo) {
                String partitionDesc = partitionInfo.getPartitionDesc();
                PartitionInfo.Builder curPartitionInfo =
                        getOrCreateCurPartitionInfo(curMap, partitionDesc, tableId).toBuilder();
                int curVersion = curPartitionInfo.getVersion();

                PartitionInfo readPartition = readPartitionMap.get(partitionDesc);
                if (readPartition == null) {
                    continue;
                }

                int newVersion = curVersion + 1;
                curPartitionInfo
                        .setVersion(newVersion)
                        .setCommitOp(commitOp)
                        .setExpression(partitionInfo.getExpression())
                        .clearSnapshot();

                newMap.put(partitionDesc, curPartitionInfo.build());
                newPartitionList.add(curPartitionInfo.build());
            }

        } else {
            throw new IllegalStateException(
                    "this operation is Illegal of the table:" + tableInfo.getTablePath());
        }

        boolean notConflict = partitionInfoDao.transactionInsert(newPartitionList, snapshotList);
        if (!notConflict) {
            switch (commitOp) {
                case AppendCommit:
                    notConflict =
                            appendConflict(
                                    tableId, partitionDescList, rawMap, newMap, snapshotList, 0);
                    break;
                case CompactionCommit:
                    notConflict =
                            compactionConflict(
                                    tableId,
                                    partitionDescList,
                                    rawMap,
                                    readPartitionMap,
                                    snapshotList,
                                    0);
                    break;
                case UpdateCommit:
                    notConflict =
                            updateConflict(
                                    tableId,
                                    partitionDescList,
                                    rawMap,
                                    readPartitionMap,
                                    snapshotList,
                                    0);
                    break;
                case MergeCommit:
                    notConflict =
                            mergeConflict(
                                    tableId, partitionDescList, rawMap, newMap, snapshotList, 0);
            }
        }

        return notConflict;
    }

