public MySqlSourceBuilder<BinarySourceRecord> mySqlSourceBuilder(
            String cdcConfigYamlPath, MySqlSourceBuilder<BinarySourceRecord> sourceBuilder)
            throws IOException {
        Path path = new Path(cdcConfigYamlPath);
        FileSystem fs = FileSystem.get(path.toUri());
        Map<String, Object> cdcParams;
        try (InputStream input = fs.open(path)) {
            cdcParams = loadAsFlatMap(input);
        }
        Properties debeziumProperties = getDebeziumProperties(cdcParams);
        Properties jdbcProperties = getJdbcProperties(cdcParams);
        if (!jdbcProperties.isEmpty()) {
            sourceBuilder.jdbcProperties(jdbcProperties);
        }
        if (!debeziumProperties.isEmpty()) {
            sourceBuilder.debeziumProperties(debeziumProperties);
        }
        if (cdcParams.containsKey(SERVER_ID.key())) {
            Object sid = cdcParams.get(SERVER_ID.key());
            if (sid != null) {
                String serverId = sid.toString();
                if (!serverId.isEmpty()) {
                    sourceBuilder.serverId(serverId);
                }
            }
        }
        if (cdcParams.containsKey(SCAN_SNAPSHOT_FETCH_SIZE.key())) {
            sourceBuilder.fetchSize(
                    Integer.parseInt(cdcParams.get(SCAN_SNAPSHOT_FETCH_SIZE.key()).toString()));
        }
        if (cdcParams.containsKey(SCAN_NEWLY_ADDED_TABLE_ENABLED.key())) {
            sourceBuilder.scanNewlyAddedTableEnabled(
                    Boolean.parseBoolean(
                            cdcParams.get(SCAN_NEWLY_ADDED_TABLE_ENABLED.key()).toString()));
        }
        if (cdcParams.containsKey(SCAN_INCREMENTAL_SNAPSHOT_CHUNK_KEY_COLUMN.key())
                && cdcParams.get(SCAN_INCREMENTAL_SNAPSHOT_CHUNK_KEY_COLUMN.key()) != null) {
            String databaseName = cdcParams.get(DATABASE_NAME.key()).toString();
            String tableName = cdcParams.get(TABLE_NAME.key()).toString();
            sourceBuilder.chunkKeyColumn(
                    new ObjectPath(databaseName, tableName),
                    cdcParams.get(SCAN_INCREMENTAL_SNAPSHOT_CHUNK_KEY_COLUMN.key()).toString());
        }
        if (cdcParams.containsKey(CHUNK_META_GROUP_SIZE.key())) {
            sourceBuilder.splitMetaGroupSize(
                    Integer.parseInt(cdcParams.get(CHUNK_META_GROUP_SIZE.key()).toString()));
        }
        if (cdcParams.containsKey(CHUNK_KEY_EVEN_DISTRIBUTION_FACTOR_LOWER_BOUND.key())) {
            sourceBuilder.distributionFactorLower(
                    Double.parseDouble(
                            cdcParams
                                    .get(CHUNK_KEY_EVEN_DISTRIBUTION_FACTOR_LOWER_BOUND.key())
                                    .toString()));
        }
        if (cdcParams.containsKey(CHUNK_KEY_EVEN_DISTRIBUTION_FACTOR_UPPER_BOUND.key())) {
            sourceBuilder.distributionFactorUpper(
                    Double.parseDouble(
                            cdcParams
                                    .get(CHUNK_KEY_EVEN_DISTRIBUTION_FACTOR_UPPER_BOUND.key())
                                    .toString()));
        }
        if (cdcParams.containsKey(CONNECT_TIMEOUT.key())) {
            sourceBuilder.connectTimeout(
                    Duration.ofSeconds(
                            Long.parseLong(cdcParams.get(CONNECT_TIMEOUT.key()).toString())));
        }
        if (cdcParams.containsKey(CONNECT_MAX_RETRIES.key())) {
            sourceBuilder.connectMaxRetries(
                    Integer.parseInt(cdcParams.get(CONNECT_MAX_RETRIES.key()).toString()));
        }
        if (cdcParams.containsKey(CONNECTION_POOL_SIZE.key())) {
            sourceBuilder.connectionPoolSize(
                    Integer.parseInt(cdcParams.get(CONNECTION_POOL_SIZE.key()).toString()));
        }
        if (cdcParams.containsKey(SCAN_STARTUP_MODE.key())) {
            sourceBuilder.startupOptions(
                    parseMysqlStartupOptions(
                            cdcParams, cdcParams.get(SCAN_STARTUP_MODE.key()).toString()));
        }
        if (cdcParams.containsKey(SCAN_INCREMENTAL_SNAPSHOT_CHUNK_SIZE.key())) {
            sourceBuilder.splitSize(
                    Integer.parseInt(
                            cdcParams.get(SCAN_INCREMENTAL_SNAPSHOT_CHUNK_SIZE.key()).toString()));
        }
        if (cdcParams.containsKey(HEARTBEAT_INTERVAL.key())) {
            sourceBuilder.heartbeatInterval(
                    Duration.ofSeconds(
                            Long.parseLong(cdcParams.get(HEARTBEAT_INTERVAL.key()).toString())));
        }
        if (cdcParams.containsKey(SERVER_ID.key())) {
            String serverId = (String) cdcParams.get(SERVER_ID.key());
            sourceBuilder.serverId(serverId);
        }
        if (cdcParams.containsKey(SCAN_INCREMENTAL_SNAPSHOT_BACKFILL_SKIP.key())) {
            sourceBuilder.skipSnapshotBackfill(
                    Boolean.parseBoolean(
                            cdcParams
                                    .get(SCAN_INCREMENTAL_SNAPSHOT_BACKFILL_SKIP.key())
                                    .toString()));
        }
        if (cdcParams.containsKey(SCAN_INCREMENTAL_CLOSE_IDLE_READER_ENABLED.key())) {
            sourceBuilder.closeIdleReaders(
                    Boolean.parseBoolean(
                            cdcParams
                                    .get(SCAN_INCREMENTAL_CLOSE_IDLE_READER_ENABLED.key())
                                    .toString()));
        }
        return sourceBuilder;
    }

public Tuple2<RowType, RowData> convert(
            TableId tableId,
            Struct struct,
            Schema schema,
            RowKind rowKind,
            List<String> primaryKeys,
            String timestampPartitionCol,
            String formatRule)
            throws Exception {
        int baseFieldCount = schema.fields().size();
        boolean hasTimestampPartitionCol = timestampPartitionCol != null;
        int arity = baseFieldCount + (hasTimestampPartitionCol ? 1 : 0);
        if (useCDC) {
            arity += 1;
        }
        BinaryRowData row = new BinaryRowData(arity);
        BinaryRowWriter writer = new BinaryRowWriter(row);
        List<Field> fields = schema.fields();
        String[] colNames = new String[arity];
        LogicalType[] colTypes = new LogicalType[arity];
        int pos = 0;
        for (Field field : fields) {
            String fieldName = field.name();
            colNames[pos] = fieldName;
            Object fieldValue = struct.getWithoutDefault(fieldName);
            boolean isPk = primaryKeys.contains(fieldName);
            boolean nullable = !isPk && field.schema().isOptional();
            colTypes[pos] = convertToLogical(field.schema(), fieldValue, nullable);

            if (fieldValue == null) {
                if (isPk) {
                    LOG.error("Encounter null value for primary key field {}", fieldName);
                    throw new IllegalArgumentException(
                            "Encounter null value for primary key field " + fieldName);
                }
                writer.setNullAt(pos);
            } else {
                Schema fieldSchema = field.schema();
                sqlSchemaAndFieldWrite(
                        writer,
                        pos,
                        fieldName,
                        fieldValue,
                        fieldSchema,
                        serverTimeZone,
                        colTypes[pos]);
            }
            pos++;
        }

        if (hasTimestampPartitionCol) {
            colNames[pos] = "pt_" + timestampPartitionCol + "_dt";
            colTypes[pos] = new VarCharType(false, Integer.MAX_VALUE);
            Object fieldValue = struct.getWithoutDefault(timestampPartitionCol);
            Schema tsColSchema = schema.field(timestampPartitionCol).schema();
            LocalDate date = null;
            Instant instant = null;
            if (tsColSchema.name().equalsIgnoreCase(Date.SCHEMA_NAME)) {
                date = TemporalConversions.toLocalDate(fieldValue);
            } else if (fieldValue instanceof Long) {
                instant = Instant.ofEpochMilli((Long) fieldValue);
            } else if (fieldValue instanceof Integer) {
                date = LocalDate.ofEpochDay((long) (Integer) fieldValue);
            } else if (fieldValue instanceof String) {
                String[] parsePatterns = {
                    "yyyy-MM-dd HH:mm:ss",
                    "yyyy-MM-dd HH:mm:ss.SSS",
                    "yyyy-MM-dd'T'HH:mm:ssX",
                    "yyyy-MM-dd'T'HH:mm:ss.SSSX",
                    "yyyy-MM-dd HH:mm:ss Z",
                    "yyyy-MM-dd HH:mm",
                    "yyyy/MM/dd HH:mm:ss",
                    "yyyy/MM/dd",
                    "yyyy-MM-dd",
                    "yyyyMMdd",
                    "yyyyMMddHHmmss"
                };
                try {
                    instant = DateUtils.parseDate(fieldValue.toString(), parsePatterns).toInstant();
                } catch (ParseException e) {
                    LOG.warn("Unable to parse date string: {}", fieldValue, e);
                }
            } else {
                try {
                    instant = Instant.parse(fieldValue.toString());
                } catch (DateTimeParseException e) {
                    LOG.warn("Unable to parse date string: {}", fieldValue, e);
                }
            }
            if (date == null && instant != null) {
                String timeZone = globalConfig.getString("table.local-time-zone", null);
                ZoneId flinkZoneId;
                if (timeZone != null) {
                    flinkZoneId = ZoneId.of(timeZone);
                } else {
                    flinkZoneId = ZoneId.systemDefault();
                }
                date = instant.atZone(flinkZoneId).toLocalDate();
                LOG.debug("use timezone: {}, calculated date: {}", flinkZoneId, date);
            }
            // we cannot find a valid date object
            if (date == null) {
                throw new SuppressRestartsException(
                        new DataException(
                                "Timestamp partition column is not a known date/timestamp type: "
                                        + tableId
                                        + "/"
                                        + timestampPartitionCol
                                        + ", value: "
                                        + fieldValue
                                        + ", class: "
                                        + fieldValue.getClass().getName()
                                        + ", schema: "
                                        + tsColSchema.name()));
            }
            if (formatRule == null) {
                formatRule = "yyyy-MM-dd";
            }
            DateTimeFormatter customFormatter = DateTimeFormatter.ofPattern(formatRule);
            String formattedDate = date.format(customFormatter);
            writer.writeString(pos, StringData.fromString(formattedDate));
            pos++;
        }
        writer.writeRowKind(rowKind);
        if (useCDC) {
            colNames[pos] = cdcColumn;
            colTypes[pos] = new VarCharType(false, Integer.MAX_VALUE);
            setCDCRowKindField(writer, rowKind, pos);
        }

        writer.complete();
        return Tuple2.of(RowType.of(colTypes, colNames), row);
    }

